/**
 * @method
 * @name ipt_liquasstAmt_onkeyup
 * @description ipt_liquasstAmt 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_liquasstAmt_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil53200.ipt_liquasstAmt_onkeyup' }); }
};

