/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const frm = (document.CapForm || { elements: [] });
    const writeYn = $c.util.getComponent('slc_writeYn');
    const acntgBasCd = $c.util.getComponent('slc_acntgBasCd');
    const audtYn = $c.util.getComponent('slc_audtYn');
    const audtOpinTpCd = $c.util.getComponent('slc_audtOpinTpCd');
    const acntclsYy = $c.util.getComponent('slc_acntclsYy');
    const acntclsYyTpCd = $c.util.getComponent('slc_listInvstgFiscyyTpCd');
    let alarmYn = false;
    for (let i = 0; i < writeYn.length; i++) {
        const tempWriteYn = writeYn[i];
        if (tempWriteYn.value === 'Y') {
            const tempAcntgBasCd = acntgBasCd[i];
            if (tempAcntgBasCd.value === '') {
                await $c.win.alert('회계기준을 입력하십시오');
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            const tempAudtYn = audtYn[i];
            if (tempAudtYn.value === '') {
                await $c.win.alert('감사여부를 입력하십시오');
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            const tempAudtOpinTpCd = audtOpinTpCd[i];
            if (tempAudtOpinTpCd.value === '') {
                await $c.win.alert('감사의견을 입력하십시오');
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            const tempAcntclsYy = acntclsYy[i];
            if (tempAcntclsYy.value === '') {
                await $c.win.alert('결산년도를 입력하십시오');
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            const tempAcntcls = acntclsYyTpCd[i];
            if (tempAcntcls.value === '') {
                await $c.win.alert('결산기를 입력하십시오');
                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        } else {
            alarmYn = true;
        }
    }
    if (alarmYn) {
        if (!await $c.win.confirm('해당없음이 선택되어 있습니다.\n해당기의 입력 항목은 삭제됩니다.\n진행하시겠습니까?')) {
            return;
        }
    }
    if ((String(((dma_pageContext.get("alreadySavedYn") ?? "")) == null ? '' : ((dma_pageContext.get("alreadySavedYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("alreadySavedYn") ?? "")) == null ? '' : ((dma_pageContext.get("alreadySavedYn") ?? "")))) === 'N') {
        $c.util.getComponent('dma_toListReq').set('fncWrtTpCd', '2');
        $c.util.getComponent('dma_toListReq').set('method', 'insertCap');
    } else {
        if ((String(((dma_pageContext.get("alreadySavedYn") ?? "")) == null ? '' : ((dma_pageContext.get("alreadySavedYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("alreadySavedYn") ?? "")) == null ? '' : ((dma_pageContext.get("alreadySavedYn") ?? "")))) === 'Y') {
            $c.util.getComponent('dma_toListReq').set('fncWrtTpCd', '2');
            $c.util.getComponent('dma_toListReq').set('method', 'updateCap');
        }
    }
    frm.action = 'cap.do';
    const nr = await scwin.tx_fn_register();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil53200n/jldfil53200n.xml", { "fncWrtTpCd": '2', "method": 'insertCap' });
    }
};

/**
 * @method
 * @name setSelectBox
 * @description set Select Box 처리
 * @param {*} listBzSeq listBzSeq
 * @returns {void}
 * @hidden N
 */
scwin.setSelectBox = function (listBzSeq) {
    const date = new Date();
    let year = "";
    const month = "";
    document.write("<option value=''>--- 선택 ---</option>");
    switch (listBzSeq) {
        case 1:
        for (let i = 6; i > 0; i--) {
            year = date.getFullYear();
            let text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
        case 2:
        for (let i = 6; i > 0; i--) {
            year = date.getFullYear();
            text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
        case 3:
        for (let i = 6; i > 0; i--) {
            year = date.getFullYear();
            text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
        case 4:
        for (let i = 6; i > 0; i--) {
            year = date.getFullYear();
            text = "";
            if ($c.util.getComponent('slc_acntclsYy').getValue() === year) {
                text = "selected";
            }
            document.write("<option value='" + year + "' " + text + ">" + year + "년</option>");
            date.setYear(date.getFullYear() - 1);
        }
        break;
    }
};

/**
 * @method
 * @name goPage
 * @description go Page 처리
 * @param {*} direction direction
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goPage = async function (direction) {
    if (!await $c.win.confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\n 이동하시겠습니까?')) {
        return;
    }
    const frm = (document.CapForm || { elements: [] });
    switch (direction) {
        case 1:
        frm.action = 'pubOfrSchdl.do';
        $c.util.getComponent('dma_toListReq').set('method', 'searchPubOfrSchdl');
        break;
        case 2:
        frm.action = 'cap.do';
        $c.util.getComponent('dma_toListReq').set('method', 'searchCap');
        break;
    }
    const nr = await scwin.tx_fn_goPage();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil53100/jldfil53100.xml", { "method": 'searchPubOfrSchdl' });
    }
};

/**
 * @method
 * @name toList
 * @description to List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.toList = async function () {
    if (!await $c.win.confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\n 이동하시겠습니까?')) {
        return;
    }
    const frm = (document.mainForm || { elements: [] });
    await scwin.tx_fn_toList();
};
